type AppendToolInvocationsRequest_ToolInvocations_Result struct {
	union json.RawMessage
}

// AppendToolInvocationsResponse Result of appending tool invocations to a call.
type AppendToolInvocationsResponse struct {
	// Added Number of tool invocations newly written
	Added int `json:"added"`

	// CallId The call the tool invocations were attached to
	CallId openapi_types.UUID `json:"callId"`

	// MetricCollectionError Present (non-null) only when `metrics` were requested but the collection job could not be started (e.g. insufficient credits, or an unknown metric id). The tool invocations were still attached — retry scoring via POST /v1/metric/collection-jobs, or re-send this request (attaching is idempotent). Null on success or when no metrics were requested.
	MetricCollectionError *string `json:"metricCollectionError"`

	// MetricCollectionJob The metric collection job triggered to (re)score the requested metrics, or null when no metrics were requested (or when scoring failed, see metricCollectionError). Track its id to fetch results from GET /v1/metric/collection-jobs/:jobId.
	MetricCollectionJob *MetricCollectionJobResponse `json:"metricCollectionJob"`

	// Skipped Number of tool invocations skipped because an identical one (same tool and timing) already existed on the call
	Skipped int `json:"skipped"`
}

